p=Path('backups/preparacion-anton-20261018');f=Path('backups/migracion-anton-final-20261018');c=json.loads((p/'accesos-anton-actual.json').read_text());s=boto3.client('s3',endpoint_url=c['B2_ENDPOINT_URL'],aws_access_key_id=c['B2_KEY_ID'],aws_secret_access_key=c['B2_APP_KEY'],region_name=c['B2_REGION'],config=Config(connect_timeout=15,read_timeout=45,retries={'max_attempts':1}));key='CM-20261007-00000235/pex_22.jpg';versions=s.list_object_versions(Bucket=c['B2_BUCKET'],Prefix=key,MaxKeys=30)['Versions'];v=next(v for v in versions if v['Key']==key);r=s.get_object(Bucket=c['B2_BUCKET'],Key=key,VersionId=v['VersionId']);data=r['Body'].read();r['Body'].close();sha=hashlib.sha256(data).hexdigest();local=f/('foto_recuperada_'+sha+'.bin');local.write_bytes(data);plan=json.loads((f/'plan_archivos.json').read_text(encoding='utf-8'));assert key not in {o['clave'] for o in plan['objetos']};plan['objetos'].append({'clave':key,'destino':key,'bytes':len(data),'sha256':sha,'md5':hashlib.md5(data).hexdigest(),'subir':True,'archivo_absoluto':str(local.resolve()),'recuperado_de_version_anton':True});(f/'plan_archivos.json').write_text(json.dumps(plan,ensure_ascii=False,indent=2),encoding='utf-8');(f/'foto_recuperada.json').write_text(json.dumps({'clave':key,'sha256':sha,'bytes':len(data),'version_recuperada':v['VersionId']},indent=2),encoding='utf-8');print('FOTO_HISTORICA_RECUPERADA_OK')
